settings.custom_liquid:
{% assign artist_url = metaobject.app_url.value %}
{% assign artist_slug = metaobject.system.handle | default: '' %}
{% assign artist_page_handle = metaobject.system.handle | default: '' %}
{% assign artist_metaobject_id = metaobject.system.id | default: '' %}
{% assign artist_page_url = metaobject.system.url | default: request.path %}
{% assign artist_name = metaobject.name | default: metaobject.system.title | default: 'Artist' %}
{% assign artist_embed_key = artist_metaobject_id | default: artist_slug | default: artist_page_handle | default: 'artist-embed' %}
{% assign artist_embed_key_encoded = artist_embed_key | url_encode %}
{% assign artist_query = 'embed=1' %}
{% if artist_embed_key != blank %}{% assign artist_query = artist_query | append: '&artclub_embed_key=' | append: artist_embed_key_encoded %}{% endif %}
{% if artist_url contains '?' %}{% assign artist_iframe_url = artist_url | append: '&' | append: artist_query %}{% else %}{% assign artist_iframe_url = artist_url | append: '?' | append: artist_query %}{% endif %}

<div class="artist-embed-wrap"
  data-artclub-track-impression="artist"
  data-artclub-track-view="artist"
  data-artclub-source="shopify_artist_embed"
  data-artclub-embed-key="{{ artist_embed_key | escape }}"
  data-artclub-page-url="{{ artist_page_url }}"
  {% if artist_page_handle != blank %}data-artclub-page-handle="{{ artist_page_handle }}"{% endif %}
  data-artclub-artist-name="{{ artist_name | escape }}"
  {% if artist_slug != blank %}data-artclub-artist-slug="{{ artist_slug }}"{% endif %}
  {% if artist_metaobject_id != blank %}data-artclub-artist-metaobject-id="{{ artist_metaobject_id }}"{% endif %}>
  <iframe
    id="artist-embed"
    data-artclub-artist-embed="true"
    data-artclub-embed-key="{{ artist_embed_key | escape }}"
    src="{{ artist_iframe_url }}"
    loading="lazy"
    style="width: 100%; min-height: 900px; border: 0;"
    allow="clipboard-read; clipboard-write">
  </iframe>
</div>

<script>
  window.addEventListener('message', function(event) {
    if (!event.data || event.data.type !== 'artclub-artist-height') return;
    var iframe = document.querySelector('iframe[data-artclub-artist-embed="true"]');
    if (!iframe || !event.data.height) return;
    var embedKey = iframe.getAttribute('data-artclub-embed-key') || '';
    if (event.data.embedKey && embedKey && embedKey !== event.data.embedKey) return;
    iframe.style.height = event.data.height + 'px';
  });
</script>
